def solve():
    q = [0] * 100
    q[0] = 202
    for i in range(1, 99):
        if i == 98:
            q[i] = (q[i-3] + q[i-2] + q[i-1]) // 10
        else:
            q[i] = (sum(q[j] for j in range(max(0, i-3), i))) // 10

    # Wait, the sum in the denominator should be the sum of the previous 3 q's.
    # Let's re-do it carefully.
    q = [0] * 100
    q[0] = 202
    for i in range(1, 99):
        if i <= 98:
            # k_i = q_{i-3} + q_{i-2} + q_{i-1} - 10q_i >= 0
            # This means 10q_i <= q_{i-3} + q_{i-2} + q_{i-1}
            # q_{i-3} is 0 if i-3 < 0
            prev_sum = 0
            for j in range(i-3, i):
                if j >= 0:
                    prev_sum += q[j]
            q[i] = prev_sum // 10

    # Now calculate S = 2025 - 7*sum(q[0:96]) - 6*q[96] - 5*q[97] - 4*q[98]
    s = 2025
    for i in range(96):
        s -= 7 * q[i]
    s -= 6 * q[96]
    s -= 5 * q[97]
    s -= 4 * q[98]
    return s, q

print(solve())
